input.replace:
test("lowercases and joins on hyphens", () => {
  assert.equal(slugify("Hello World"), "hello-world");
});

test("collapses runs of whitespace and strips punctuation", () => {
  assert.equal(slugify("  Hello,   World!  "), "hello-world");
});

test("strips characters that are not letters, digits, or hyphens", () => {
  assert.equal(slugify("Hello@World#123!"), "helloworld123");
});
